package com.footballacademy.config.data;
import org.slf4j.Logger; import org.slf4j.LoggerFactory; import org.springframework.boot.CommandLineRunner; import org.springframework.core.Ordered; import org.springframework.core.annotation.Order; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.stereotype.Component; import java.sql.Connection; import java.util.Locale;
@Component @Order(Ordered.HIGHEST_PRECEDENCE+5) public class ScoutingArchitectureSchemaFix implements CommandLineRunner { private static final Logger log=LoggerFactory.getLogger(ScoutingArchitectureSchemaFix.class); private final JdbcTemplate jdbc; public ScoutingArchitectureSchemaFix(JdbcTemplate jdbc){this.jdbc=jdbc;} public void run(String...args){try{if(!isMySql())return; createTables();}catch(Exception ex){log.warn("Could not auto-fix scouting architecture schema: {}", ex.getMessage());}} private boolean isMySql() throws Exception{ if(jdbc.getDataSource()==null)return false; try(Connection c=jdbc.getDataSource().getConnection()){String p=c.getMetaData().getDatabaseProductName(); String n=p==null?"":p.toLowerCase(Locale.ROOT); return n.contains("mysql")||n.contains("mariadb");}} private void createTables(){ jdbc.execute("CREATE TABLE IF NOT EXISTS scouters (user_id BIGINT NOT NULL, academy_id BIGINT NULL, region VARCHAR(255), speciality VARCHAR(255), experience_level VARCHAR(255), active BIT(1) DEFAULT b'1', PRIMARY KEY(user_id), INDEX idx_scouter_academy(academy_id))"); jdbc.execute("CREATE TABLE IF NOT EXISTS scouting_assignments (id BIGINT NOT NULL AUTO_INCREMENT, academy_id BIGINT, scouter_id BIGINT, division_id BIGINT, assigned_at DATETIME(6), status VARCHAR(40), notes VARCHAR(1000), PRIMARY KEY(id), INDEX idx_assignment_scouter(scouter_id), INDEX idx_assignment_division(division_id))"); jdbc.execute("CREATE TABLE IF NOT EXISTS scouting_reports (id BIGINT NOT NULL AUTO_INCREMENT, player_id BIGINT, scouter_id BIGINT, academy_id BIGINT, match_id BIGINT, technical_score DOUBLE, tactical_score DOUBLE, physical_score DOUBLE, mental_score DOUBLE, potential_score DOUBLE, style_fit_score DOUBLE, recommendation VARCHAR(500), notes TEXT, status VARCHAR(40), created_at DATETIME(6), updated_at DATETIME(6), PRIMARY KEY(id), INDEX idx_report_player(player_id), INDEX idx_report_academy(academy_id))"); jdbc.execute("CREATE TABLE IF NOT EXISTS scouting_criteria (id BIGINT NOT NULL AUTO_INCREMENT, name VARCHAR(255) NOT NULL, domain VARCHAR(255), weight DOUBLE, description VARCHAR(1000), active BIT(1), PRIMARY KEY(id))"); jdbc.execute("CREATE TABLE IF NOT EXISTS scouting_criterion_scores (id BIGINT NOT NULL AUTO_INCREMENT, report_id BIGINT, criterion_id BIGINT, score DOUBLE, comment VARCHAR(1000), PRIMARY KEY(id), INDEX idx_score_report(report_id))"); jdbc.execute("CREATE TABLE IF NOT EXISTS match_events (id BIGINT NOT NULL AUTO_INCREMENT, match_id BIGINT, player_id BIGINT, event_type VARCHAR(40), minute INT, second INT, x_position DOUBLE, y_position DOUBLE, success BIT(1), pressure_level VARCHAR(255), intensity INT, note VARCHAR(1000), PRIMARY KEY(id), INDEX idx_event_match(match_id), INDEX idx_event_player(player_id))"); jdbc.execute("CREATE TABLE IF NOT EXISTS player_attribute_snapshots (id BIGINT NOT NULL AUTO_INCREMENT, player_id BIGINT, match_id BIGINT, captured_at DATETIME(6), speed DOUBLE, acceleration DOUBLE, agility DOUBLE, stamina DOUBLE, strength DOUBLE, positioning DOUBLE, decision_making DOUBLE, vision DOUBLE, off_ball_movement DOUBLE, composure DOUBLE, PRIMARY KEY(id))"); jdbc.execute("CREATE TABLE IF NOT EXISTS player_progressions (id BIGINT NOT NULL AUTO_INCREMENT, player_id BIGINT, metric_name VARCHAR(255), old_value DOUBLE, new_value DOUBLE, change_rate DOUBLE, recorded_at DATETIME(6), PRIMARY KEY(id))"); jdbc.execute("CREATE TABLE IF NOT EXISTS video_assets (id BIGINT NOT NULL AUTO_INCREMENT, match_id BIGINT, player_id BIGINT, video_url VARCHAR(1000), duration_seconds BIGINT, resolution VARCHAR(255), uploaded_at DATETIME(6), PRIMARY KEY(id))"); jdbc.execute("CREATE TABLE IF NOT EXISTS video_analyses (id BIGINT NOT NULL AUTO_INCREMENT, video_asset_id BIGINT, status VARCHAR(40), detected_events INT, heatmap_url VARCHAR(1000), highlight_url VARCHAR(1000), analysis_score DOUBLE, completed_at DATETIME(6), PRIMARY KEY(id))"); jdbc.execute("CREATE TABLE IF NOT EXISTS talent_scores (id BIGINT NOT NULL AUTO_INCREMENT, player_id BIGINT, score DOUBLE, confidence DOUBLE, risk_level VARCHAR(255), generated_at DATETIME(6), PRIMARY KEY(id))"); jdbc.execute("CREATE TABLE IF NOT EXISTS injury_records (id BIGINT NOT NULL AUTO_INCREMENT, player_id BIGINT, injury_type VARCHAR(255), severity VARCHAR(255), start_date DATE, end_date DATE, recovered BIT(1), notes VARCHAR(1000), PRIMARY KEY(id))"); } }
